	ops = append(ops, diffStringField(base, []string{"match", "ip", "address", "prefix-list"}, prev.MatchIPAddressPrefixList, cur.MatchIPAddressPrefixList)...)

	ops = append(ops, diffIntField(base, []string{"match", "ip", "address", "prefix-len"}, prev.MatchIPAddressPrefixLen, cur.MatchIPAddressPrefixLen)...)

